using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalFountainWater{
static FinalFountainWater(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalFountainWater.request")||EditorApplication.isCompiling)return;File.Delete("FinalFountainWater.request");Run();}
static void Photo(UnityEngine.SceneManagement.Scene scene,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,p,target,name});
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var fountains=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Fountain_")).ToArray();foreach(var f in fountains){var m=f.sharedMesh;var collider=f.GetComponent<MeshCollider>().sharedMesh;string backup="FinalEnvironmentRoadBackup/FountainWater-20261012/"+m.name+".asset";if(!File.Exists(backup))File.Copy(AssetDatabase.GetAssetPath(m),backup);var p=m.vertices;var ids=m.triangles;var info=m.uv2;var plot=new List<Vector2>(Enumerable.Repeat(Vector2.zero,p.Length));var centers=new List<Vector2>(Enumerable.Repeat(Vector2.zero,p.Length));int water=0;for(int i=0;i<p.Length;i++){if(Mathf.RoundToInt(info[i].x)!=13)continue;var center=f.transform.TransformPoint(p[i]);float radius=0;for(int j=i;j<i+3;j++)radius=Mathf.Max(radius,Vector3.Distance(center,f.transform.TransformPoint(p[j])));float impact=radius>2?radius*.43f:.15f;for(int j=i;j<i+3;j++){plot[j]=new Vector2(radius,impact);centers[j]=new Vector2(center.x,center.z);}i+=2;water++;}m.SetUVs(3,plot);m.SetUVs(4,centers);EditorUtility.SetDirty(m);if(!p.SequenceEqual(m.vertices)||!ids.SequenceEqual(m.triangles)||collider!=f.GetComponent<MeshCollider>().sharedMesh)throw new Exception("Fountain geometry changed");log.AppendLine(f.name+" water triangles="+water+"; geometry and collider unchanged");}
AssetDatabase.SaveAssets();var mat=fountains[0].GetComponent<MeshRenderer>().sharedMaterial;Shader.SetGlobalFloat("_CityGardenPreviewEnabled",1);try{foreach(var f in fountains){var p=f.GetComponent<Renderer>().bounds.center;for(int frame=0;frame<2;frame++){Shader.SetGlobalFloat("_CityGardenPreviewTime",frame*1.25f);Photo(scene,p+new Vector3(9,7,-10),p,"Fountain-Water-"+f.name+"-"+frame);}}}finally{Shader.SetGlobalFloat("_CityGardenPreviewEnabled",0);}int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS two fountains; animated turquoise water, specular ripples, splash-ring foam and broken falling streams; shared atlas/material retained; no added renderer, texture, realtime light, reflection camera, particle simulation or collider; shader errors=0");
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/FountainWaterReport.txt",log.ToString());}}
